SELECT r.id, r.token_budget, r.tokens_used, r.time_used_seconds, r.autonomous_turns_used, r.consecutive_no_progress, r.conversation_id, r.objective, r.status, r.status_reason, r.pause_reason, r.controller_spec, r.last_continuation_fingerprint, r.created_at, r.updated_at FROM (SELECT t.* FROM  (SELECT c.* , 0 AS should_delete FROM goal c)  t) r WHERE $criteria.CompositeIn("r", $WriterKeys)